import options from '../options';

/**
 * Find the closest error boundary to a thrown error and call it
 * @param {object} error The thrown value
 * @param {import('../internal').VNode} vnode The vnode that threw
 * the error that was caught (except for unmounting when this parameter
 * is the highest parent that was being unmounted)
 */
export function _catchError(error, vnode) {
	/** @type {import('../internal').Component} */
	let component, ctor, handled;

	const wasHydrating = vnode._hydrating;

	for (; (vnode = vnode._parent); ) {
		if ((component = vnode._component) && !component._processingException) {
			try {
				ctor = component.constructor;

				if (ctor && ctor.getDerivedStateFromError != null) {
					component.setState(ctor.getDerivedStateFromError(error));
					handled = component._dirty;
				}

				if (component.componentDidCatch != null) {
					component.componentDidCatch(error);
					handled = component._dirty;
				}

				// This is an error boundary. Mark it as having bailed out, and whether it was mid-hydration.
				if (handled) {
					vnode._hydrating = wasHydrating;
					return (component._pendingError = component);
				}
			} catch (e) {
				error = e;
			}
		}
	}

	throw error;
}

function setStyle(style, key, value, nonDimensional) {
	if (key[0] === '-') {
		style.setProperty(key, value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || nonDimensional.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

export function PropertySetter() {
	this._eventProxy = eventProxy;
	this._captureProxy = eventProxyCapture;
}

/**
 * Set a property value on a DOM node
 * @param {import('../util').DomPropTarget} target The DOM node to modify
 * @param {import('../create-element').PropChange} change The property mutation
 * @param {import('../constants').HostPropNames} names Host property names
 */
PropertySetter.prototype.setProperty = function(target, change, names) {
	let useCapture, nameLower, proxy;

	if (target.isSvg && change.name == 'className') change.name = 'class';

	if (change.name === 'style') {
		if (typeof change.value == 'string') {
			target.style.cssText = change.value;
		} else {
			if (typeof change.oldValue == 'string') {
				target.style.cssText = change.oldValue = '';
			}

			if (change.oldValue) {
				for (change.name in change.oldValue) {
					if (!(change.value && change.name in change.value)) {
						setStyle(target.style, change.name, '', names.nonDimensional);
					}
				}
			}

			if (change.value) {
				for (change.name in change.value) {
					if (
						!change.oldValue ||
						change.value[change.name] !== change.oldValue[change.name]
					) {
						setStyle(
							target.style,
							change.name,
							change.value[change.name],
							names.nonDimensional
						);
					}
				}
			}
		}
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	else if (change.name[0] === 'o' && change.name[1] === 'n') {
		useCapture =
			change.name !== (change.name = change.name.replace(/Capture$/, ''));
		nameLower = change.name.toLowerCase();
		if (nameLower in target.element) change.name = nameLower;
		change.name = change.name.slice(2);

		if (!target.element._listeners) target.element._listeners = {};
		target.element._listeners[change.name + useCapture] = change.value;

		proxy = useCapture ? this._captureProxy : this._eventProxy;
		if (change.value) {
			if (!change.oldValue)
				target.element.addEventListener(change.name, proxy, useCapture);
		} else {
			target.element.removeEventListener(change.name, proxy, useCapture);
		}
	} else if (
		change.name !== names.list &&
		change.name !== names.tagName &&
		change.name !== names.form &&
		change.name !== 'type' &&
		change.name !== 'size' &&
		change.name !== 'download' &&
		change.name !== 'href' &&
		!target.isSvg &&
		change.name in target.element
	) {
		target.element[change.name] = change.value == null ? '' : change.value;
	} else if (
		typeof change.value != 'function' &&
		change.name !== 'dangerouslySetInnerHTML'
	) {
		if (change.name !== (change.name = change.name.replace(/xlink:?/, ''))) {
			if (change.value == null || change.value === false) {
				target.element.removeAttributeNS(
					'http://www.w3.org/1999/xlink',
					change.name.toLowerCase()
				);
			} else {
				target.element.setAttributeNS(
					'http://www.w3.org/1999/xlink',
					change.name.toLowerCase(),
					change.value
				);
			}
		} else if (
			change.value == null ||
			(change.value === false &&
				// ARIA-attributes have a different notion of boolean values.
				// The value `false` is different from the attribute not
				// existing on the DOM, so we can't remove it. For non-boolean
				// ARIA-attributes we could treat false as a removal, but the
				// amount of exceptions would cost us too many bytes. On top of
				// that other VDOM frameworks also always stringify `false`.
				!/^ar/.test(change.name))
		) {
			target.element.removeAttribute(change.name);
		} else {
			target.element.setAttribute(change.name, change.value);
		}
